[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>LearnForge — Build & Sell Online Courses, Coaching, Memberships & More</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;500;600;700&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --color-primary: #2563EB;
      --color-secondary: #3B82F6;
      --color-cta: #F97316;
      --color-background: #F8FAFC;
      --color-text: #1E293B;
      --color-text-light: #64748B;
      --color-white: #FFFFFF;
      --color-border: #E2E8F0;
      --space-xs: 0.25rem;
      --space-sm: 0.5rem;
      --space-md: 1rem;
      --space-lg: 1.5rem;
      --space-xl: 2rem;
      --space-2xl: 3rem;
      --space-3xl: 4rem;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px rgba(0,0,0,0.15);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --font-heading: 'Poppins', sans-serif;
      --font-body: 'Open Sans', sans-serif;
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--color-text);
      background: var(--color-white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); font-weight: 600; line-height: 1.2; }

    a { text-decoration: none; color: inherit; }

    img { max-width: 100%; height: auto; display: block; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 var(--space-lg);
    }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--color-border);
      z-index: 1000;
      padding: 0 var(--space-lg);
    }

    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .nav-logo {
      font-family: var(--font-heading);
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--color-primary);
      display: flex;
      align-items: center;
      gap: var(--space-sm);
    }

    .nav-logo svg { width: 32px; height: 32px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: var(--space-xl);
      list-style: none;
    }

    .nav-links a {
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--color-text);
      transition: color 200ms ease;
      cursor: pointer;
    }

    .nav-links a:hover { color: var(--color-primary); }

    .nav-cta {
      background: var(--color-cta);
      color: white;
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 0.9375rem;
      transition: all 200ms ease;
      cursor: pointer;
      border: none;
    }

    .nav-cta:hover {
      opacity: 0.9;
      transform: translateY(-1px);
    }

    .nav-mobile-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: var(--space-sm);
    }

    /* Hero */
    .hero {
      padding: calc(72px + var(--space-3xl)) 0 var(--space-3xl);
      background: linear-gradient(135deg, #F8FAFC 0%, #EFF6FF 100%);
      overflow: hidden;
    }

    .hero-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--space-3xl);
      align-items: center;
    }

    .hero-text h1 {
      font-size: clamp(2rem, 4vw, 3rem);
      margin-bottom: var(--space-lg);
      color: var(--color-text);
    }

    .hero-text p {
      font-size: 1.125rem;
      color: var(--color-text-light);
      margin-bottom: var(--space-xl);
      max-width: 500px;
    }

    .hero-buttons {
      display: flex;
      gap: var(--space-md);
      flex-wrap: wrap;
    }

    .btn-primary {
      background: var(--color-cta);
      color: white;
      padding: 14px 28px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 1rem;
      transition: all 200ms ease;
      cursor: pointer;
      border: none;
      display: inline-flex;
      align-items: center;
      gap: var(--space-sm);
    }

    .btn-primary:hover { opacity: 0.9; transform: translateY(-1px); }

    .btn-secondary {
      background: transparent;
      color: var(--color-primary);
      border: 2px solid var(--color-primary);
      padding: 14px 28px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 1rem;
      transition: all 200ms ease;
      cursor: pointer;
    }

    .btn-secondary:hover { background: var(--color-primary); color: white; }

    .hero-tabs {
      display: flex;
      gap: var(--space-sm);
      margin-bottom: var(--space-lg);
      background: var(--color-white);
      padding: 6px;
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-sm);
      width: fit-content;
    }

    .hero-tab {
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 0.875rem;
      cursor: pointer;
      transition: all 200ms ease;
      border: none;
      background: transparent;
      color: var(--color-text-light);
    }

    .hero-tab.active {
      background: var(--color-primary);
      color: white;
    }

    .hero-tab:not(.active):hover { background: #EFF6FF; }

    .hero-preview {
      background: var(--color-white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      overflow: hidden;
      min-height: 340px;
      position: relative;
    }

    .preview-header {
      background: var(--color-background);
      padding: var(--space-md);
      border-bottom: 1px solid var(--color-border);
      display: flex;
      gap: var(--space-sm);
    }

    .preview-dot {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: #E2E8F0;
    }

    .preview-dot:first-child { background: #EF4444; }
    .preview-dot:nth-child(2) { background: #F59E0B; }
    .preview-dot:nth-child(3) { background: #22C55E; }

    .preview-content {
      padding: var(--space-lg);
    }

    .preview-creator, .preview-student { display: none; }
    .preview-creator.active, .preview-student.active { display: block; }

    .preview-student .mini-sidebar {
      width: 200px;
      background: var(--color-background);
      border-radius: var(--radius-sm);
      padding: var(--space-md);
      float: right;
      margin-left: var(--space-md);
    }

    .preview-student .mini-course-card {
      background: white;
      border: 1px solid var(--color-border);
      border-radius: var(--radius-sm);
      padding: var(--space-md);
      margin-bottom: var(--space-sm);
    }

    .preview-creator .mini-header {
      background: var(--color-primary);
      color: white;
      padding: var(--space-md);
      border-radius: var(--radius-sm);
      margin-bottom: var(--space-md);
    }

    .preview-creator .mini-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--space-sm);
      margin-bottom: var(--space-md);
    }

    .preview-creator .mini-stat {
      background: var(--color-background);
      padding: var(--space-md);
      border-radius: var(--radius-sm);
      text-align: center;
    }

    .preview-creator .mini-stat-label {
      font-size: 0.75rem;
      color: var(--color-text-light);
    }

    .preview-creator .mini-stat-value {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--color-text);
    }

    .preview-creator .mini-table {
      background: var(--color-background);
      border-radius: var(--radius-sm);
      padding: var(--space-md);
    }

    .preview-creator .mini-table-row {
      display: flex;
      justify-content: space-between;
      padding: var(--space-sm) 0;
      border-bottom: 1px solid var(--color-border);
    }

    .preview-creator .mini-table-row:last-child { border: none; }

    /* Stats Bar */
    .stats-bar {
      background: var(--color-primary);
      padding: var(--space-2xl) 0;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--space-xl);
      text-align: center;
    }

    .stat-item { color: white; }

    .stat-value {
      font-family: var(--font-heading);
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 700;
      display: block;
    }

    .stat-label {
      font-size: 1rem;
      opacity: 0.9;
    }

    /* Products Section */
    .products {
      padding: var(--space-3xl) 0;
      background: var(--color-white);
    }

    .section-header {
      text-align: center;
      margin-bottom: var(--space-2xl);
    }

    .section-header h2 {
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      margin-bottom: var(--space-md);
    }

    .section-header p {
      font-size: 1.125rem;
      color: var(--color-text-light);
      max-width: 600px;
      margin: 0 auto;
    }

    .products-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--space-lg);
    }

    .product-card {
      background: var(--color-background);
      border-radius: var(--radius-md);
      padding: var(--space-xl);
      transition: all 200ms ease;
      cursor: pointer;
      border: 1px solid transparent;
    }

    .product-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-4px);
      border-color: var(--color-primary);
    }

    .product-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--color-primary), var(--color-secondary));
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: var(--space-lg);
    }

    .product-icon svg {
      width: 28px;
      height: 28px;
      color: white;
    }

    .product-card h3 {
      font-size: 1.125rem;
      margin-bottom: var(--space-sm);
    }

    .product-card p {
      font-size: 0.875rem;
      color: var(--color-text-light);
    }

    /* Why Choose Us Tabs */
    .why-choose {
      padding: var(--space-3xl) 0;
      background: var(--color-background);
    }

    .why-tabs {
      display: flex;
      justify-content: center;
      gap: var(--space-sm);
      margin-bottom: var(--space-xl);
      flex-wrap: wrap;
    }

    .why-tab {
      padding: 12px 24px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 0.875rem;
      cursor: pointer;
      transition: all 200ms ease;
      border: none;
      background: var(--color-white);
      color: var(--color-text);
      box-shadow: var(--shadow-sm);
    }

