      tab.addEventListener('click', () => {
        heroTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        if (tab.dataset.tab === 'creator') {
          previewCreator.classList.add('active');
          previewStudent.classList.remove('active');
        } else {
          previewStudent.classList.add('active');
          previewCreator.classList.remove('active');
        }
      });
    });

    // Why Choose Us Tabs
    const whyTabs = document.querySelectorAll('.why-tab');
    const whyPanels = document.querySelectorAll('.why-panel');

    whyTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        whyTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        whyPanels.forEach(p => p.classList.remove('active'));
        document.querySelector(`.why-panel[data-panel="${tab.dataset.panel}"]`).classList.add('active');
      });
    });

    // Testimonials Carousel
    const carouselTrack = document.querySelector('.carousel-track');
    const carouselCards = document.querySelectorAll('.testimonial-card');
    const carouselBtns = document.querySelectorAll('.carousel-btn');
    const carouselDots = document.querySelector('.carousel-dots');
    let currentSlide = 0;

    carouselCards.forEach((_, i) => {
      const dot = document.createElement('button');
      dot.classList.add('carousel-dot');
      if (i === 0) dot.classList.add('active');
      dot.addEventListener('click', () => goToSlide(i));
      carouselDots.appendChild(dot);
    });

    function goToSlide(index) {
      currentSlide = index;
      carouselTrack.style.transform = `translateX(-${index * 100}%)`;
      document.querySelectorAll('.carousel-dot').forEach((d, i) => {
        d.classList.toggle('active', i === index);
      });
    }

    carouselBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        if (btn.classList.contains('prev')) {
          goToSlide((currentSlide - 1 + carouselCards.length) % carouselCards.length);
        } else {
          goToSlide((currentSlide + 1) % carouselCards.length);
        }
      });
    });

